function openStreakModal() {

    const modal = document.getElementById("streak-modal");

    if (!modal) return;

    

    const count = currentStudent?.streak_days || 0;

    const titleEl = document.getElementById("streak-modal-title");

    if (titleEl) titleEl.innerText = `🔥 ${count}일 연속 학습 달성!`;

    

    // 7일 출석 도장 렌더링 (월~일)

    const weekContainer = document.getElementById("streak-week-days");

    if (weekContainer) {

        const dayNames = ['월', '화', '수', '목', '금', '토', '일'];

        const today = new Date();

        const currentDayIndex = (today.getDay() + 6) % 7; // 월=0, 일=6

        

        let html = '';

        dayNames.forEach((name, idx) => {

            let isAchieved = false;

            let isToday = (idx === currentDayIndex);

            if (idx <= currentDayIndex && count > 0) {

                if (currentDayIndex - idx < count) {

                    isAchieved = true;

                }

            }

            

            const badgeBg = isAchieved ? '#f97316' : (isToday ? 'rgba(249, 115, 22, 0.3)' : '#334155');

            const textColor = isAchieved ? '#ffffff' : (isToday ? '#fed7aa' : '#64748b');

            const icon = isAchieved ? '🔥' : (idx === 6 ? '👑' : '-');

            const border = isToday ? '2px solid #f97316' : 'none';

            

            html += `

                <div style="text-align: center;">

                    <div style="font-size: 0.72rem; color: ${isToday ? '#fb923c' : '#94a3b8'}; margin-bottom: 4px; font-weight: ${isToday ? '800' : '600'};">${name}${isToday ? '<br><span style="font-size:0.62rem;">(오늘)</span>' : ''}</div>

                    <div style="width: 32px; height: 32px; border-radius: 50%; background: ${badgeBg}; color: ${textColor}; border: ${border}; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; font-weight: 800; margin: 0 auto; box-shadow: ${isAchieved ? '0 2px 8px rgba(249, 115, 22, 0.4)' : 'none'};">

                        ${icon}

                    </div>

                </div>

            `;

        });

        weekContainer.innerHTML = html;

    }

    

    modal.style.display = "flex";

}

function formatCleanSubjectTitle(rawTitle) {

    if (!rawTitle) return "자습";

    let t = rawTitle.trim();

    if (t.includes("국어")) return "국어";

    if (t.includes("수학") || t.includes("미적") || t.includes("기하") || t.includes("확통")) return "수학";

    if (t.includes("영어")) return "영어";

    if (t.includes("한국사")) return "한국사";

    if (t.includes("과탐") || t.includes("사탐") || t.includes("탐구") || t.includes("물리") || t.includes("화학") || t.includes("생명") || t.includes("지구")) return "탐구";

    if (t.includes("자습") || t.includes("독서실") || t.includes("몰입")) return "자습";

    if (t.includes("모의고사") || t.includes("시험")) return "모의고사";

    if (t.includes("과외") || t.includes("튜터")) return "과외";

    if (t.includes("학원") || t.includes("강의")) return "학원";

    if (t.length <= 4) return t;

    return t.replace(/집중|학습|수업|특강|공부|시간|대비/g, '').trim() || t.slice(0, 4);

}

// 🏛️ 대학교 영문 이니셜 및 엠블럼 매퍼 (가상학생증용)

function getUniversityInitial(univName) {

    if (!univName) return "PALIN";

    const u = univName.trim();

    if (u.includes("서울대")) return "SNU";

    if (u.includes("연세대")) return "YONSEI";

    if (u.includes("고려대")) return "KU";

    if (u.includes("카이스트") || u.includes("KAIST")) return "KAIST";

    if (u.includes("포항공대") || u.includes("포스텍")) return "POSTECH";

    if (u.includes("성균관대")) return "SKKU";

    if (u.includes("한양대")) return "HYU";

    if (u.includes("서강대")) return "SOGANG";

    if (u.includes("중앙대")) return "CAU";

    if (u.includes("경희대")) return "KHU";

    if (u.includes("한국외대")) return "HUFS";

    if (u.includes("서울시립대")) return "UOS";

    if (u.includes("이화여대")) return "EWHA";

    if (u.includes("건국대")) return "KU";

    if (u.includes("동국대")) return "DGU";

    if (u.includes("홍익대")) return "HIU";

    if (u.includes("가톨릭대")) return "CUK";

    if (u.includes("울산대")) return "UU";

    if (u.includes("아주대")) return "AJOU";

    if (u.includes("인하대")) return "INHA";

    if (u.includes("경북대")) return "KNU";

    if (u.includes("부산대")) return "PNU";

    if (u.includes("전남대")) return "JNU";

    if (u.includes("전북대")) return "JBNU";

    if (u.includes("충남대")) return "CNU";

    if (u.includes("충북대")) return "CBNU";

    return u.slice(0, 4).toUpperCase();

}

