function updateTargetBanner() {

    const targetUnivEl = document.getElementById("banner-target-univ");

    const baselineUnivEl = document.getElementById("banner-baseline-univ");

    const target = (currentStudent && currentStudent.target_univ && currentStudent.target_univ !== "-") ? currentStudent.target_univ : (localStorage.getItem("cached_target_univ") || "연세대학교 의예과");

    const baseline = (currentStudent && currentStudent.baseline_univ && currentStudent.baseline_univ !== "-") ? currentStudent.baseline_univ : (localStorage.getItem("cached_baseline_univ") || "서울대학교 화학생물공학부");

    if (targetUnivEl) targetUnivEl.innerText = target;
    if (baselineUnivEl) baselineUnivEl.innerText = baseline;

    // 🏫 정시/수시 합격예측 화면의 목표 대학 & 마지노선 대학 실시간 동기화
    const dispTarget = document.getElementById("disp-target-univ");
    const dispBase = document.getElementById("disp-baseline-univ");
    const predTargetInput = document.getElementById("pred-target-univ");
    if (dispTarget) dispTarget.innerText = target;
    if (dispBase) dispBase.innerText = baseline;
    if (predTargetInput && !predTargetInput.value && target && target !== "-") {
        predTargetInput.value = target.split(' ')[0] || target;
    }

    // 🎨 목표 대학 상징 앰비언트 테마 & 세리프 영문 워터마크 실시간 적용

    applyUniversityTheme(target);

    // D-Day 실시간 자동 계산 렌더링 (매일 자정 및 로드 시 실시간 반영)

    const ddayEl = document.getElementById("banner-dday");

    const ddayTitleEl = document.getElementById("banner-dday-title");

    const activeDate = localStorage.getItem('pinnedDDayDate') || (currentStudent && currentStudent.dday_date) || "2026-11-19";

    const activeTitle = localStorage.getItem('pinnedDDayTitle') || (currentStudent && currentStudent.dday_title) || "2027 수능";

    

    if (ddayEl) ddayEl.innerText = calculateDDay(activeDate);

    if (ddayTitleEl) ddayTitleEl.innerText = formatDDayTitle(activeTitle);

    // 🌲 포레스트 목표 대학 로고 & 엠블럼 렌더링

    if (currentStudent) {

        const emblemEl = document.getElementById("target-symbol-emblem");

        const logoNameEl = document.getElementById("target-logo-name");

        if (emblemEl) emblemEl.innerText = getMedicalSymbolIcon(currentStudent.medical_symbol);

        if (logoNameEl) logoNameEl.innerText = `${currentStudent.target_univ || "목표 대학"} 수호 중`;

    }

}

