// Student Academy Code Application
async function handleApplyAcademyCode() {
    const inputEl = document.getElementById("mypage-academy-code-input");
    const code = inputEl ? inputEl.value.trim().toUpperCase() : "";
    if (!code) {
        alert("학원 초대 코드를 입력해 주세요.");
        return;
    }
    const sid = (currentStudent && currentStudent.id) ? currentStudent.id : parseInt(localStorage.getItem('studentId') || '1', 10);
    try {
        const res = await fetch("/api/student/apply-academy-code", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ student_id: sid, academy_code: code })
        });
        const data = await res.json();
        if (res.ok) {
            alert(`✅ ${data.message}`);
            if (typeof fetchStudentInfo === 'function') fetchStudentInfo(sid);
        } else {
            alert(data.detail || "초대 코드 등록 실패");
        }
    } catch(e) {
        alert("코드 등록 처리 중 오류가 발생했습니다.");
    }
}

function setPrimaryDDay(title, dateStr) {

    localStorage.setItem('pinnedDDayTitle', title);

    localStorage.setItem('pinnedDDayDate', dateStr);

    

    // 1페이지 배너 즉시 반영

    const ddayEl = document.getElementById("banner-dday");

    const ddayTitleEl = document.getElementById("banner-dday-title");

    if (ddayEl) ddayEl.innerText = calculateDDay(dateStr);

    if (ddayTitleEl) ddayTitleEl.innerText = title.replace("2027학년도 ", "").replace("2026학년도 ", "");

    

    alert(`📌 [${title}] 일정이 1페이지 홈 배너의 D-Day로 설정되었습니다!`);

    renderAdmissionCalendar();

}

function renderAdmissionCalendar() {

    const rawCalendarData = [

        { title: "2026학년도 9월 모의평가 (수능 바로미터)", date: "2026-09-02", cat: "평가원" },

        { title: "2027학년도 대입 수시모집 원서접수", date: "2026-09-07", cat: "원서접수" },

        { title: "2027학년도 대학수학능력시험 (본 수능)", date: "2026-11-19", cat: "수능시험" },

        { title: "2027학년도 대입 정시모집 원서접수", date: "2026-12-28", cat: "원서접수" }

    ];

    const listEl = document.getElementById("admission-calendar-list");

    if (!listEl) return;

    listEl.innerHTML = "";

    

    const pinnedDate = localStorage.getItem('pinnedDDayDate') || "2026-11-19";

    

    rawCalendarData.forEach(item => {

        const ddayText = calculateDDay(item.date);

        // 이미 지난 일정(D+)은 자동 제외

        if (ddayText.startsWith("D+")) return;

        

        const isPinned = (item.date === pinnedDate);

        const isUrgent = ddayText.startsWith("D-") && parseInt(ddayText.replace("D-", "")) <= 30;

        const ddayColor = isUrgent ? "background: #ef4444; color: white;" : "background: #3b82f6; color: white;";

        const pinBtnText = isPinned ? "✅ 노출 중" : "📌 1페이지 노출";

        const pinBtnStyle = isPinned 

            ? "background: #10b981; color: white; border: none;" 

            : "background: rgba(255,255,255,0.08); color: var(--text-primary); border: 1px solid var(--glass-border);";

            

        listEl.innerHTML += `

            <div class="calendar-card" style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; margin-bottom: 8px;">

                <div style="flex: 1; min-width: 0;">

                    <div class="calendar-item-title" style="font-weight: 800; font-size: 0.85rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.title}</div>

                    <div style="font-size: 0.72rem; color: var(--text-secondary); margin-top: 2px;">📅 ${item.date} (${item.cat})</div>

                </div>

                <div style="display: flex; align-items: center; gap: 8px; flex-shrink: 0;">

                    <button class="btn" style="padding: 4px 8px; font-size: 0.72rem; border-radius: 6px; font-weight: 700; ${pinBtnStyle}" onclick="setPrimaryDDay('${item.title}', '${item.date}')">

                        ${pinBtnText}

                    </button>

                    <div class="calendar-dday" style="${ddayColor} padding: 4px 8px; border-radius: 8px; font-size: 0.8rem; font-weight: 800; min-width: 48px; text-align: center;">

                        ${ddayText}

                    </div>

                </div>

            </div>

        `;

    });

}

function openMyPageModal() {
    if (currentStudent) {
        updateHeaderUI();
        const fullname = document.getElementById("mypage-student-fullname");
        if (fullname) fullname.innerText = `${currentStudent.name} 학생`;
        const sub = document.getElementById("mypage-student-sub");
        const gradeText = currentStudent.grade === 4 ? "N수생" : currentStudent.grade === 0 ? "기타" : `${currentStudent.grade}학년`;
        if (sub) sub.innerText = `${currentStudent.high_school || "일반고"} ${gradeText} | ${currentStudent.region || "경기도 성남시 분당구"}`;

        const hsInput = document.getElementById("edit-high-school");
        if (hsInput) hsInput.value = currentStudent.high_school || "";

        // 💎 B2B 학원 지원 & 티어 뱃지 렌더링
        const activeBadge = document.getElementById("mypage-tier-active-badge");
        const pendingBadge = document.getElementById("mypage-tier-pending-badge");
        const freeBadge = document.getElementById("mypage-tier-free-badge");
        const sponsorText = document.getElementById("mypage-academy-sponsor-text");
        const pendingAcadName = document.getElementById("mypage-pending-academy-name");
        const tierTitle = document.getElementById("mypage-tier-title");

        const approvalStatus = currentStudent.academy_approval_status || "NONE";
        const acadCode = currentStudent.academy_code;
        const b2cTier = currentStudent.b2c_subscription_tier || "TIER_1_FREE";

        if (acadCode && approvalStatus === "APPROVED") {
            // Case 1: 가맹 학원 원장님 전액 지원 승인 완료 학생 (Tier 3 무료)
            if (pendingBadge) pendingBadge.style.display = "none";
            if (freeBadge) freeBadge.style.display = "none";
            if (activeBadge) {
                activeBadge.style.display = "flex";
                if (tierTitle) tierTitle.innerText = "Tier 3 마스터 AI 활성화";
                const acadName = (acadCode.includes("ILWON") || acadCode.includes("일원")) ? "일원학원" : (currentStudent.academy_name || acadCode);
                if (sponsorText) sponsorText.innerText = `${acadName} 원장님 전액 지원 (월 99,000원 혜택)`;
            }
        } else if (approvalStatus === "PENDING") {
            // Case 2: 학원 초대코드 입력 후 원장님 승인 대기 중
            if (activeBadge) activeBadge.style.display = "none";
            if (freeBadge) freeBadge.style.display = "none";
            if (pendingBadge) {
                pendingBadge.style.display = "block";
                if (pendingAcadName) pendingAcadName.innerText = currentStudent.pending_tenant_code || "학원";
            }
        } else if (b2cTier === "TIER_2_PARENT") {
            // Case 3: B2C Tier 2 스탠다드 구독 (월 19,900원)
            if (pendingBadge) pendingBadge.style.display = "none";
            if (freeBadge) freeBadge.style.display = "none";
            if (activeBadge) {
                activeBadge.style.display = "flex";
                if (tierTitle) tierTitle.innerText = "Tier 2 스탠다드 AI 활성화";
                if (sponsorText) sponsorText.innerText = "월 19,900원 멤버십 이용 중";
            }
        } else if (b2cTier === "TIER_3_MASTER") {
            // Case 4: B2C Tier 3 마스터 구독 (월 99,000원)
            if (pendingBadge) pendingBadge.style.display = "none";
            if (freeBadge) freeBadge.style.display = "none";
            if (activeBadge) {
                activeBadge.style.display = "flex";
                if (tierTitle) tierTitle.innerText = "Tier 3 마스터 AI 활성화";
                if (sponsorText) sponsorText.innerText = "월 99,000원 프리미엄 플랜";
            }
        } else {
            // Case 5: B2C Tier 1 무료 체험 회원 (신규 가입 기본값)
            if (activeBadge) activeBadge.style.display = "none";
            if (pendingBadge) pendingBadge.style.display = "none";
            if (freeBadge) freeBadge.style.display = "flex";
        }

        // 지역 (시도 / 시군구 분리 로드)
        const curRegion = currentStudent.region || "서울특별시 강남구";
        const rParts = curRegion.split(" ");
        let rawSido = rParts[0] || "서울특별시";
        let curSigungu = rParts.slice(1).join(" ") || "강남구";

        // 17개 시도 키값 정확 매칭
        const allSidos = typeof DEFAULT_REGIONS_DATA !== 'undefined' ? Object.keys(DEFAULT_REGIONS_DATA) : [];
        const curSido = allSidos.find(s => s === rawSido || s.startsWith(rawSido) || rawSido.startsWith(s)) || "서울특별시";
        if (typeof setupRegionSelectors === 'function') {
            setupRegionSelectors("edit-region-sido", "edit-region-sigungu", curSido, curSigungu);
        }
    }
    const modal = document.getElementById("mypage-modal");
    if (modal) modal.style.display = "flex";
}

function closeMyPageModal() {
    const modal = document.getElementById("mypage-modal");
    if (modal) modal.style.display = "none";
}

function toggleMyPageEditSection() {
    const body = document.getElementById("mypage-edit-body");
    const icon = document.getElementById("mypage-edit-toggle-icon");
    const status = document.getElementById("mypage-edit-toggle-status");
    if (!body) return;
    if (body.style.display === "none" || !body.style.display) {
        body.style.display = "block";
        if (icon) icon.style.transform = "rotate(180deg)";
        if (status) status.innerText = "접기";
    } else {
        body.style.display = "none";
        if (icon) icon.style.transform = "rotate(0deg)";
        if (status) status.innerText = "설정 변경";
    }
}
window.toggleMyPageEditSection = toggleMyPageEditSection;

function switchRole(role) {

    activeRole = role;

    document.querySelectorAll(".role-toggle-btn").forEach(el => el.classList.remove("active"));

    document.querySelector(`.role-toggle-btn[data-role="${role}"]`).classList.add("active");

    

    // 역할별 화면 노출 제어

    if (role === "tutor") {

        document.getElementById("tutor-only-views").style.display = "block";

        document.getElementById("student-only-views").style.display = "none";

        

        // 내 선생님 프로필 정보 바인딩

        if (currentStudent && currentStudent.tutor_profile) {

            const tp = currentStudent.tutor_profile;

            document.getElementById("tutor-my-univ-badge").innerText = tp.univ_emblem || `🎓 ${tp.university}`;

            document.getElementById("tutor-my-school-badge").innerText = tp.high_school_emblem || `🏫 ${tp.high_school_type || '출신고'}`;

            document.getElementById("edit-tutor-bio").value = tp.bio || "";

            document.getElementById("edit-tutor-link").value = tp.contact_link || "";

            // 🎯 원장 승인 상태 실시간 반영

            const statusBadge = document.getElementById("tutor-verify-status-badge");

            if (statusBadge) {

                if (tp.is_verified) {

                    statusBadge.innerHTML = `<span style="color: #10b981; font-weight: 800; background: rgba(16, 185, 129, 0.15); padding: 4px 10px; border-radius: 12px; border: 1px solid rgba(16, 185, 129, 0.3);">✅ 인증 승인완료</span>`;

                } else {

                    statusBadge.innerHTML = `<span style="color: #f59e0b; font-weight: 800; background: rgba(245, 158, 11, 0.15); padding: 4px 10px; border-radius: 12px; border: 1px solid rgba(245, 158, 11, 0.3);">⏳ 원장 승인심사중...</span>`;

                }

            }

        }

    } else {

        document.getElementById("tutor-only-views").style.display = "none";

        document.getElementById("student-only-views").style.display = "block";

    }

}


function switchTab(tabId) {
    if (!tabId) return;
    
    // 1. 모든 page-view 숨기기
    document.querySelectorAll(".page-view").forEach(page => {
        page.style.display = "none";
    });
    
    // 2. 대상 page-view 표시
    const targetPage = document.getElementById(tabId);
    if (targetPage) {
        targetPage.style.display = "block";
    }
    
    // 3. 네비게이션 액티브 스타일 갱신
    document.querySelectorAll(".nav-item").forEach(item => {
        if (item.getAttribute("data-tab") === tabId) {
            item.classList.add("active");
        } else {
            item.classList.remove("active");
        }
    });
    
    // 4. 페이지별 데이터 로드
    if (tabId === "page1") {
        if (typeof loadPage1Data === 'function') loadPage1Data();
        if (typeof loadTimetable === 'function') loadTimetable();
    } else if (tabId === "page2") {
        if (typeof loadPage2Data === 'function') loadPage2Data();
    } else if (tabId === "page3") {
        if (typeof loadPage3Data === 'function') loadPage3Data();
    } else if (tabId === "page4") {
        if (typeof loadAcademyHubView === 'function') loadAcademyHubView();
    }
    
    window.scrollTo({ top: 0, behavior: "smooth" });
}
window.switchTab = switchTab;

function switchSubTabPage2(subTab) {
    if (!subTab) return;
    document.querySelectorAll(".subtab-view-p2").forEach(view => {
        view.style.display = "none";
    });
    document.querySelectorAll("#p2-tabs .tab-btn").forEach(btn => {
        if (btn.getAttribute("data-sub") === subTab) {
            btn.classList.add("active");
        } else {
            btn.classList.remove("active");
        }
    });
    
    const target = document.getElementById(`p2-${subTab}`);
    if (target) target.style.display = "block";
    
    if (subTab === "calendar") {
        if (typeof renderAdmissionCalendar === 'function') renderAdmissionCalendar();
    } else if (subTab === "archive") {
        if (typeof loadExamMaterials === 'function') loadExamMaterials();
    } else if (subTab === "predict") {
        if (typeof loadPage2Data === 'function') loadPage2Data();
        if (typeof loadUniversityList === 'function') loadUniversityList();
    }
}
window.switchSubTabPage2 = switchSubTabPage2;

