// 🏆 8. 마이크로 지역/고교 랭킹 리더보드 (Strava 모델)

// ==========================================

async function loadMicroRankings() {
    const listEl = document.getElementById("micro-ranking-list");
    if (!listEl) return;

    const sid = (currentStudent && currentStudent.id) ? currentStudent.id : parseInt(localStorage.getItem('studentId') || '1', 10);
    const myRegion = currentStudent?.region || "성남시 분당구";
    const mySchool = currentStudent?.high_school || "낙생고등학교";

    const regEl = document.getElementById("my-ranking-region-name");
    const schEl = document.getElementById("my-ranking-school-name");
    const regPosEl = document.getElementById("my-ranking-region-pos");
    const schPosEl = document.getElementById("my-ranking-school-pos");
    if (regEl) regEl.innerText = myRegion;
    if (schEl) schEl.innerText = mySchool;
    if (regPosEl) regPosEl.innerText = "-";
    if (schPosEl) schPosEl.innerText = "-";

    try {
        const res = await fetch(`/api/gamification/micro-rankings?student_id=${sid}`);
        if (res.ok) {
            const data = await res.json();
            if (regEl) regEl.innerText = data.region_name || myRegion;
            if (schEl) schEl.innerText = data.school_name || mySchool;
            if (regPosEl) regPosEl.innerText = data.region_pos_str || "-";
            if (schPosEl) schPosEl.innerText = data.school_pos_str || "-";

            listEl.innerHTML = "";
            (data.rankers || []).forEach(r => {
                const medal = (r.studySeconds && r.studySeconds > 0)
                    ? (r.rank === 1 ? "🥇" : (r.rank === 2 ? "🥈" : (r.rank === 3 ? "🥉" : `${r.rank}위`)))
                    : "-";
                const isDayMode = document.body.classList.contains('day-mode');
                const bg = r.isMe 
                    ? (isDayMode ? "#fef3c7" : "rgba(234, 179, 8, 0.15)") 
                    : (isDayMode ? "#ffffff" : "rgba(255,255,255,0.03)");
                const border = r.isMe 
                    ? "1.5px solid #eab308" 
                    : (isDayMode ? "1px solid #cbd5e1" : "1px solid rgba(255,255,255,0.06)");

                listEl.innerHTML += `
                    <div style="display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; background: ${bg}; border-radius: 8px; border: ${border}; margin-bottom: 4px;">
                        <div style="display: flex; align-items: center; gap: 10px;">
                            <span style="font-weight: 800; font-size: 0.95rem; min-width: 24px;">${medal}</span>
                            <div>
                                <div style="font-weight: 700; font-size: 0.85rem; color: var(--text-primary);">
                                    ${r.name} ${r.isMe ? '<span style="background: #fbbf24; color: #000; font-size: 0.65rem; padding: 1px 5px; border-radius: 4px; font-weight: 900;">ME</span>' : ''}
                                </div>
                                <div style="font-size: 0.72rem; color: var(--text-secondary);">${r.school} · ${r.region}</div>
                            </div>
                        </div>
                        <div style="text-align: right;">
                            <div style="font-weight: 800; font-size: 0.85rem; color: #fbbf24;">${r.studyHours}</div>
                            <div style="font-size: 0.7rem; color: #f97316; font-weight: 700;">연속 ${r.streak}일 달성</div>
                        </div>
                    </div>
                `;
            });
        }
    } catch(e) {
        console.warn("loadMicroRankings error:", e);
    }

    // Render School Guild List
    const guildListEl = document.getElementById("p3-school-guild-list");
    if (guildListEl) {
        try {
            const sid = (currentStudent && currentStudent.id) ? currentStudent.id : 1;
            const matrixRes = await fetch(`/api/ranking/matrix?student_id=${sid}`);
            if (matrixRes.ok) {
                const matrixData = await matrixRes.json();
                const schools = matrixData.school_ranking || [];
                if (schools.length === 0) {
                    guildListEl.innerHTML = '<div style="text-align:center; color:#94a3b8; padding:14px;">집계된 학교 랭킹이 없습니다.</div>';
                } else {
                    guildListEl.innerHTML = schools.map((s, idx) => {
                        const champBadge = s.is_champion ? '<span style="background:linear-gradient(135deg, #f59e0b, #d97706); color:#000; font-weight:900; padding:2px 6px; border-radius:4px; font-size:0.68rem; margin-left:4px;">🏆 1위 챔피언</span>' : '';
                        const bg = idx === 0 ? 'background:rgba(245, 158, 11, 0.15); border:1px solid rgba(245, 158, 11, 0.3);' : (idx < 3 ? 'background:rgba(99, 102, 241, 0.1);' : 'background:rgba(255,255,255,0.03);');
                        return `
                            <div style="display:flex; justify-content:space-between; align-items:center; padding:10px 12px; border-radius:8px; ${bg}">
                                <div style="display:flex; align-items:center; gap:8px;">
                                    <span style="font-weight:900; font-size:0.95rem; color:${idx === 0 ? '#fbbf24' : '#ffffff'};">${idx + 1}위</span>
                                    <span style="font-weight:700; font-size:0.85rem; color:#f8fafc;">${s.school}</span>
                                    ${champBadge}
                                </div>
                                <div style="font-weight:800; font-size:0.85rem; color:#818cf8;">
                                    +${s.total_points.toLocaleString()}P <span style="font-size:0.7rem; color:#94a3b8; font-weight:500;">(${s.student_count}명)</span>
                                </div>
                            </div>
                        `;
                    }).join('');
                }
            }
        } catch (e) {
            console.warn("Guild list load:", e);
        }
    }
}

function switchP3RankingMode(mode) {
    const pBtn = document.getElementById("p3-rank-btn-personal");
    const gBtn = document.getElementById("p3-rank-btn-guild");
    const pView = document.getElementById("p3-rank-personal-view");
    const gView = document.getElementById("p3-rank-guild-view");

    if (mode === 'PERSONAL') {
        if (pBtn) pBtn.className = 'subtab-btn-hub active';
        if (gBtn) gBtn.className = 'subtab-btn-hub';
        if (pView) pView.style.display = 'block';
        if (gView) gView.style.display = 'none';
    } else {
        if (pBtn) pBtn.className = 'subtab-btn-hub';
        if (gBtn) gBtn.className = 'subtab-btn-hub active';
        if (pView) pView.style.display = 'none';
        if (gView) gView.style.display = 'block';
    }
}

